const replySearchFrom = (replyAnchor < oldestAllowed ? oldestAllowed : replyAnchor).toISOString();
const reservedDomain = /(^|\.)example(?:\.|$)|\.(?:invalid|localhost|test)$|^(?:invalid|localhost|test)$/i.test(emailDomain);
