  const from = String(entry.from?.emailAddress?.address || entry.sender?.emailAddress?.address || '').toLowerCase();
  return from === customerEmail && Boolean(entry.subject || entry.bodyPreview || entry.body?.content);
}).map(entry => {
  const subject = String(entry.subject || entry.conversationTopic || '').normalize('NFKC').replace(/\s+/g, ' ').trim().slice(0, 300);
  const excerpt = String(entry.bodyPreview || entry.body?.content || '').normalize('NFKC').replace(/<[^>]*>/g, ' ').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2000);
  const haystack = norm(subject + ' ' + excerpt);
  const referenceMatch = refs.some(ref => haystack.includes(ref));
  const correlated = refs.length > 0 ? referenceMatch : /(?:neontrip|angebot|leuchtschild)/i.test(subject);
  const at = new Date(entry.receivedDateTime || entry.sentDateTime || entry.createdDateTime || 0);
  return { id: String(entry.id || '').trim(), subject, excerpt, correlated, received_at: Number.isFinite(at.getTime()) ? at.toISOString() : null, timestamp: Number.isFinite(at.getTime()) ? at.getTime() : 0 };
}).filter(reply => reply.id && reply.excerpt && reply.id !== handledReplyMessageId).sort((a, b) => b.timestamp - a.timestamp);
const correlated = replies.filter(reply => reply.correlated);
const latest = correlated[0] || null;
const route = lookupFailed ? 'block' : (latest ? 'classify' : (replies.length > 0 ? 'block' : 'send'));
return [{ json: {
  ...item,
  offer_link: String(validated.offer_link || ''),
  offer_id: String(validated.offer_id || ''),
  offer_number: validated.offer_number || null,
