  reply_preflight_safe: route === 'send',
  reply_route: route,
  reply_count: replies.length,
  reply_message_id: latest?.id || null,
  reply_subject: latest?.subject || null,
  reply_excerpt: latest?.excerpt || null,
  reply_received_at: latest?.received_at || null,
  block_reason: lookupFailed ? 'outlook_reply_lookup_failed' : (replies.length > 0 && !latest ? 'uncorrelated_customer_reply' : null),
} }];

const item = $json || {};
