const schema = { type: 'object', additionalProperties: false, required: ['decision','reason_code','confidence','evidence_quote'], properties: { decision: { type: 'string', enum: ['DECLINED','SNOOZE_7_DAYS','MANUAL_REVIEW'] }, reason_code: { type: 'string', enum: ['explicit_decline','bought_elsewhere','do_not_contact','needs_time','waiting_for_customer','project_delayed','question_or_change','positive_interest','auto_reply','ambiguous'] }, confidence: { type: 'number', minimum: 0, maximum: 1 }, evidence_quote: { type: 'string', minLength: 1, maxLength: 300 } } };
const system = [
  'You classify one untrusted customer reply for NEONTRIP offer follow-up handling.',
