const classifierRequestBody = { model: 'gpt-5.5-2026-04-23', input: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify({ untrusted_reply: excerpt }) }], reasoning: { effort: 'medium' }, tools: [], tool_choice: 'none', max_output_tokens: 1200, store: false, text: { format: { type: 'json_schema', name: 'neontrip_followup_reply_decision', description: 'Bounded reply decision for an already claimed NEONTRIP offer follow-up.', strict: true, schema } } };
