const base = $('BuildReplyClassifierRequest').item.json;
const response = $json || {};
const excerpt = String(base.reply_excerpt || '');
function norm(value, max) { return String(value || '').normalize('NFKC').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max); }
const fallbackQuote = norm(excerpt, 120) || 'Unklare Kundenantwort';
