try {
  if (response.status === 'completed' && response.incomplete_details == null && Array.isArray(response.output)) {
    const texts = response.output.filter(part => part && part.type === 'message' && part.status === 'completed' && Array.isArray(part.content)).flatMap(part => part.content).filter(part => part && part.type === 'output_text' && typeof part.text === 'string').map(part => part.text);
    if (texts.length === 1) raw = JSON.parse(texts[0]);
  }
} catch {}
const allowedKeys = ['confidence','decision','evidence_quote','reason_code'];
const exactKeys = raw && typeof raw === 'object' && !Array.isArray(raw) && Object.keys(raw).sort().join('|') === allowedKeys.join('|');
const decisions = new Set(['DECLINED','SNOOZE_7_DAYS','MANUAL_REVIEW']);
const reasons = new Set(['explicit_decline','bought_elsewhere','do_not_contact','needs_time','waiting_for_customer','project_delayed','question_or_change','positive_interest','auto_reply','ambiguous']);
