  const proposedQuote = norm(raw.evidence_quote, 300);
  if (proposedQuote && excerpt.toLocaleLowerCase('de-DE').includes(proposedQuote.toLocaleLowerCase('de-DE'))) { decision = raw.decision; reasonCode = raw.reason_code; confidence = raw.confidence; quote = proposedQuote; }
}
const declineNegation = /\b(?:(?:noch|bisher)\s+nicht\s+(?:abgesagt|abgelehnt)|keine\s+absage|nicht\s+(?:abgesagt|abgelehnt))\b/i;
const explicitDecline = /(?:\bkein(?:e[\p{L}]*)?\s+(?:interesse|bedarf)\b|\bhat\s+(?:abgesagt|abgelehnt)\b|\b(?:anderweitig|woanders)[^.]{0,100}\b(?:vergeben|bestellt|gekauft|beauftragt)\b|\bbitte\b[^.]{0,100}\b(?:keine|nicht)\b[^.]{0,100}\b(?:e-?mails?|nachrichten|kontakt)\b|\bnicht\s+mehr\s+(?:kontaktieren|anschreiben|benötigt|benoetigt)\b|\bdo\s+not\s+contact\b|\bnot\s+interested\b|\b(?:will\s+not|won't)\s+proceed\b|\bwent\s+with\s+another\b|\b(?:cancelled|canceled|declined)\b)/iu;
