if (decision === 'SNOOZE_7_DAYS' && (confidence < 0.8 || !new Set(['needs_time','waiting_for_customer','project_delayed']).has(reasonCode) || !explicitSnooze.test(quote))) { decision = 'MANUAL_REVIEW'; reasonCode = 'ambiguous'; confidence = 0; }
